def main(args: dict) -> dict:
    company_person_content = args.get("company_person_content") or ""

    # 你的实际输入是 list，需要先取第一个对象里的 text
    if isinstance(company_person_content, list):
        if company_person_content and isinstance(company_person_content[0], dict):
            company_person_content = company_person_content[0].get("text") or ""
        else:
            company_person_content = ""

    company_person_arr = []

    match = re.search(
        r'###\s*主要人员（\d+\s*条）\s*(.*?)(?=\n##\s|\Z)',
        company_person_content,
        re.S
    )

    if match:
        section = match.group(1)

        # | 1 | 蒋章 | 董事 |
        pattern = r'^\|\s*\d+\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|?\s*$'

        for name, position in re.findall(pattern, section, re.M):
            name = name.strip()
            if name:
                company_person_arr.append(name)

    return {
        "company_person_arr": company_person_arr
    }

import re
import time

def main(args: dict) -> dict:
    query = args.get('query', '')
    raw = (query or '').strip()
    parts = re.split(r'[\n,，;；、]+', raw)
    companies = []
    seen = set()
    for part in parts:
        name = re.sub(r'\s+', ' ', part).strip(' \t\r\n"\'')
        if name and name not in seen:
            companies.append(name)
            seen.add(name)
        if len(companies) >= 5:
            break
    if not companies:
        companies = ['未提供企业名称']
    return {
        'companies': companies,
        'company_count': len(companies),
        'request_id': f'DD-{int(time.time())}',
    }

import re
import json

def _to_text(value):
    if value is None:
        return ''
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        return '\n'.join(_to_text(item) for item in value)
    if isinstance(value, dict):
        direct = value.get('text') or value.get('data')
        if direct:
            return str(direct)
        return '\n'.join(_to_text(item) for item in value.values())
    return str(value)

def main(args: dict) -> dict:
    basic_text = args.get('basic_text')
    search_text = args.get('search_text')
    basic = _to_text(basic_text)
    search = _to_text(search_text)

    payload = basic_text
    if isinstance(basic_text, str):
        try:
            payload = json.loads(basic_text)
        except Exception:
            payload = None

    target_keys = {
        'legalrepresentativename', 'legalrepresentative',
        'legalpersonname', 'legalperson', '法定代表人', '法人',
    }

    def find_person(value):
        if isinstance(value, dict):
            for key, item in value.items():
                if str(key).replace('_', '').lower() in target_keys:
                    if isinstance(item, dict):
                        candidate = item.get('name') or item.get('humanName')
                    else:
                        candidate = item
                    if candidate and 1 < len(str(candidate).strip()) <= 30:
                        return str(candidate).strip()
            for item in value.values():
                candidate = find_person(item)
                if candidate:
                    return candidate
        elif isinstance(value, list):
            for item in value:
                candidate = find_person(item)
                if candidate:
                    return candidate
        return ''

    person = find_person(payload) if payload is not None else ''
    if not person:
        for pattern in [
            r'法定代表人\s*[|:：]\s*([^|\n]{2,20})',
            r'法人\s*[|:：]\s*([^|\n]{2,20})',
            r'法定代表人\s+([^\s|]{2,20})',
        ]:
            match = re.search(pattern, basic)
            if match:
                person = match.group(1).strip(' *：:')
                break

    company_id = ''
    for line in search.splitlines():
        if '|' not in line:
            continue
        cells = [cell.strip() for cell in line.split('|') if cell.strip()]
        if not cells or not re.fullmatch(r'\d+', cells[0]):
            continue
        candidates = [
            cell for cell in cells[1:]
            if re.fullmatch(r'\d{5,15}', cell)
        ]
        if candidates:
            company_id = candidates[-1]
            break

    if not company_id:
        for pattern in [
            r'(?:企业ID|company_id|companyId)\s*[：:=|]\s*[\"\']?(\d{5,20})',
            r'\"company_id\"\s*:\s*\"?(\d{5,20})',
        ]:
            match = re.search(pattern, search, re.IGNORECASE)
            if match:
                company_id = match.group(1)
                break

    return {
        'representative_name': person or '未识别',
        'representative_found': bool(person),
        'company_id': company_id,
    }

