import re

def main(args: dict) -> dict:
    content = args.get("content") or []

    text = ""

    # 兼容：
    # content = [{"text": "..."}]
    # content = [[{"text": "..."}]]
    if isinstance(content, list) and content:
        first = content[0]

        if isinstance(first, list):
            if first and isinstance(first[0], dict):
                text = first[0].get("text") or ""
        elif isinstance(first, dict):
            text = first.get("text") or ""

    # 提取 company_name
    company_name = ""

    match = re.search(
        r'\|\s*company_name\s*\|\s*([^|]+?)\s*\|',
        text
    )

    if match:
        company_name = match.group(1).strip()

    # 企业风险摘要：核心工具
    core_tools = [
        {
            "tool_name": "get_risk_overview",
            "arguments": {}
        },
        {
            "tool_name": "get_judicial_case",
            "arguments": {
                "page": 1,
                "page_size": 10
            }
        },
        {
            "tool_name": "get_judgment_debtor_info",
            "arguments": {
                "page": 1,
                "page_size": 10
            }
        },
        {
            "tool_name": "get_dishonest_info",
            "arguments": {
                "page": 1,
                "page_size": 10
            }
        },
        {
            "tool_name": "get_high_consumption_restriction",
            "arguments": {
                "page": 1,
                "page_size": 10
            }
        },
        {
            "tool_name": "get_administrative_penalty",
            "arguments": {
                "page": 1,
                "page_size": 10
            }
        },
        {
            "tool_name": "get_serious_violation",
            "arguments": {
                "page": 1,
                "page_size": 10
            }
        },
        {
            "tool_name": "get_equity_freeze",
            "arguments": {
                "page": 1,
                "page_size": 10
            }
        },
        {
            "tool_name": "get_equity_ratio",
            "arguments": {
                "page": 1,
                "page_size": 10
            }
        }
    ]

    # 提取当前企业实际可用的工具
    available_tools = re.findall(
        r'^\|\s*`([^`]+)`\s*\|\s*可用\s*\|',
        text,
        re.M
    )

    available_set = set(available_tools)

    # 构造单工具调用数组
    call_tool_arguments = []

    for tool in core_tools:
        if tool["tool_name"] in available_set:
            call_tool_arguments.append({
                "company_name": company_name,
                "tool_name": tool["tool_name"],
                "arguments": tool["arguments"]
            })

        # 最多 9 个
        if len(call_tool_arguments) >= 9:
            break

    return {
        "call_tool_arguments": call_tool_arguments
    }
